-- HMM (HMM_PARTNER) Prohibited & Restricted Cargo List based on IMDG Code 42-24
-- Source: carriers/hmm.pdf  ("2026 Prohibited and Restricted List-Rev1", Valid as from 15th Oct. 2026; UN table page dated 6th Oct. 2026)
-- Supersedes: "HMM - 2025 Prohibited and Restricted List" (version_no 2025, effective 2025-02-11)
--
-- Status convention (Sinokor books HMM as a PARTNER -> the PARTNER column decides):
--   PROHIBITED  = Partner column "X"  (incl. HMM=R / Partner=X "HMM booking on HMM vessel only" -> condition_type HMM_BOOKING_ONLY)
--   RESTRICTED  = Partner column "R"  (conditions kept in condition_text / document_required / *_condition columns)
--   Class-wide rows (unno='ALL'): Class 1 / 2.1 / 6.2 / 7 PROHIBITED; other classes RESTRICTED (page-1 live-reefer table + DG approval number policy),
--   same convention as the 2025 load so unlisted UN numbers keep showing "조건부 가능 / 제한".
--   COMMON rows (unno='COMMON') are guidance only (carrier-check.js does not use them for the verdict).
--   Class 5.2 ALL is a single RESTRICTED row (PRC/HK origin and explosive sub-risk prohibited, otherwise SADT 60C) so that
--   unlisted 5.2 UN numbers are not blanket-prohibited by decideStatus().
--
-- Changes vs previous edition flagged by HMM (pink rows) : UN3378 R->X, UN2031 (+HUCHEMS 3H1 ban), UN2794/2795/2800 (LOI liability statement),
--   UN3166 (Ni-MH hybrid acceptable, used vehicle prohibited). Also: UN3171 Partner X->R, RFDRY prohibited in live reefer,
--   new UN 3553 / 3554 / 3555 (42nd amendment), 3551 / 3552 / 3558 sodium-ion, 1442 / 1502 / 2968 / 3251 / 1204 / 2803 / 2969 / 1387 added.
--
-- Run this in Supabase SQL Editor after reviewing the rows (delete + insert, idempotent).

delete from public.dg_carrier_rules
where carrier_group = 'HMM_PARTNER';

insert into public.dg_carrier_rules (
  carrier_group, carrier_name, class_no, unno, psn, status, remark_code, remark_text, condition_type, condition_text, booking_scope, origin_condition, destination_condition, container_condition, stowage_condition, document_required, source_file, version_no, effective_date, sort_order, is_active
) values
('HMM_PARTNER','HMM Partner','ALL','COMMON','HMM DG Policy - Providing DG Approval Number','RESTRICTED','DG_APPROVAL','DG shipments loaded onto HMM operating vessels in all Asian ports and Australian ports must be provided a DG approval number when the final DG booking list is submitted to HMM local offices. All DG shipments without a DG approval number are strictly prohibited to load onto HMM vessels. Include the DG approval No. in the booking forecast / CLL for all DG bookings.','COMMON_REMARK','DG shipments loaded onto HMM operating vessels in all Asian ports and Australian ports must be provided a DG approval number when the final DG booking list is submitted to HMM local offices. All DG shipments without a DG approval number are strictly prohibited to load onto HMM vessels. Include the DG approval No. in the booking forecast / CLL for all DG bookings.','PARTNER',null,null,null,null,'HMM DG approval number','HMM - 2026 Prohibited and Restricted List Rev1 (IMDG 42-24)','2026.10 Rev1','2026-10-15',10,true),
('HMM_PARTNER','HMM Partner','ALL','COMMON','Prohibit hand writing DG placard on CNTR','PROHIBITED','PLACARD','Hand-written DG placard on container is prohibited.','COMMON_REMARK','Hand-written DG placard on container is prohibited.','PARTNER',null,null,null,null,null,'HMM - 2026 Prohibited and Restricted List Rev1 (IMDG 42-24)','2026.10 Rev1','2026-10-15',20,true),
('HMM_PARTNER','HMM Partner','ALL','COMMON','STABILIZED substances with SP386','RESTRICTED','SP386','Need SAPT under IMDG Code 7.3.7.2.3.','COMMON_REMARK','Need SAPT under IMDG Code 7.3.7.2.3.','PARTNER',null,null,null,null,'SAPT information','HMM - 2026 Prohibited and Restricted List Rev1 (IMDG 42-24)','2026.10 Rev1','2026-10-15',30,true),
('HMM_PARTNER','HMM Partner','ALL','COMMON','Substances of IMDG Code SP900','PROHIBITED','SP900','Substances of IMDG Code SP900 are prohibited: AMMONIUM HYPOCHLORITE; AMMONIUM NITRATE liable to self-heating sufficient to initiate a decomposition; AMMONIUM NITRITES and mixtures of an inorganic nitrite with an ammonium salt; CHLORIC ACID, AQUEOUS SOLUTION with more than 10% chloric acid; ETHYL NITRITE pure; HYDROCYANIC ACID, AQUEOUS SOLUTION (HYDROGEN CYANIDE, AQUEOUS SOLUTION) with more than 20% hydrogen cyanide; HYDROGEN CHLORIDE, REFRIGERATED LIQUID; HYDROGEN CYANIDE SOLUTION, IN ALCOHOL with more than 45% hydrogen cyanide; MERCURY OXYCYANIDE pure; METHYL NITRITE; PERCHLORIC ACID with more than 72% acid, by mass; SILVER PICRATE, dry or wetted with less than 30% water by mass; ZINC AMMONIUM NITRITE.','COMMON_REMARK','Substances of IMDG Code SP900 are prohibited: AMMONIUM HYPOCHLORITE; AMMONIUM NITRATE liable to self-heating sufficient to initiate a decomposition; AMMONIUM NITRITES and mixtures of an inorganic nitrite with an ammonium salt; CHLORIC ACID, AQUEOUS SOLUTION with more than 10% chloric acid; ETHYL NITRITE pure; HYDROCYANIC ACID, AQUEOUS SOLUTION (HYDROGEN CYANIDE, AQUEOUS SOLUTION) with more than 20% hydrogen cyanide; HYDROGEN CHLORIDE, REFRIGERATED LIQUID; HYDROGEN CYANIDE SOLUTION, IN ALCOHOL with more than 45% hydrogen cyanide; MERCURY OXYCYANIDE pure; METHYL NITRITE; PERCHLORIC ACID with more than 72% acid, by mass; SILVER PICRATE, dry or wetted with less than 30% water by mass; ZINC AMMONIUM NITRITE.','PARTNER',null,null,null,null,null,'HMM - 2026 Prohibited and Restricted List Rev1 (IMDG 42-24)','2026.10 Rev1','2026-10-15',40,true),
('HMM_PARTNER','HMM Partner','ALL','COMMON','DG in Live Refrigerated (Reefer) Containers','RESTRICTED','LIVE_REEFER','1. Prohibited in live reefer: Class 1 / 2.1 / 3 (F/P < +23C) / 6.2 / 7 / RFDRY (non-operated reefer container). 2. Restricted in live reefer: Class 2.2 / 2.3 / 3 (F/P >= +23C) / 4.1 / 4.2 / 4.3 / 5.1 / 5.2 / 6.1 / 8 / 9 - acceptable subject to quality control purpose only; if sub-risk is a prohibited class it is prohibited; all temperature-controlled DG in live RF CNTR is prohibited; reefer temperature for Class 3 or sub-risk 3 shall be set at least 10C below flashpoint; Class 9 acceptable except UN3314 and UN2211 (prohibited in reefer).','COMMON_REMARK','1. Prohibited in live reefer: Class 1 / 2.1 / 3 (F/P < +23C) / 6.2 / 7 / RFDRY (non-operated reefer container). 2. Restricted in live reefer: Class 2.2 / 2.3 / 3 (F/P >= +23C) / 4.1 / 4.2 / 4.3 / 5.1 / 5.2 / 6.1 / 8 / 9 - acceptable subject to quality control purpose only; if sub-risk is a prohibited class it is prohibited; all temperature-controlled DG in live RF CNTR is prohibited; reefer temperature for Class 3 or sub-risk 3 shall be set at least 10C below flashpoint; Class 9 acceptable except UN3314 and UN2211 (prohibited in reefer).','PARTNER',null,null,'Live reefer: see condition',null,null,'HMM - 2026 Prohibited and Restricted List Rev1 (IMDG 42-24)','2026.10 Rev1','2026-10-15',50,true),
('HMM_PARTNER','HMM Partner','ALL','COMMON','CARBON (including non-activated / Carbon Black) / ACTIVATED CARBON / CHARCOAL','PROHIBITED','CARBON','All including Non-DG are prohibited. Acceptable for HMM booking on HMM vessel only if the carbon black manufacturer is OCI (from Korea), Orion Engineered Carbons or Phillips Carbon Black (from India) - Partner treated as prohibited.','HMM_BOOKING_ONLY','All including Non-DG are prohibited. Acceptable for HMM booking on HMM vessel only if the carbon black manufacturer is OCI (from Korea), Orion Engineered Carbons or Phillips Carbon Black (from India) - Partner treated as prohibited.','PARTNER',null,null,null,null,null,'HMM - 2026 Prohibited and Restricted List Rev1 (IMDG 42-24)','2026.10 Rev1','2026-10-15',60,true),
